describe('column codec rules (#465)', () => {
  for (const [type, codec, expected] of CASES) {
    test(`${type} ${JSON.stringify(codec)}`, () => {
      const definition = table({
        database: 'app',
        name: 'events',
        engine: 'MergeTree()',
        primaryKey: ['id'],
        orderBy: ['id'],
        columns: [{ name: 'id', type: 'UInt64' }, { name: 'c', type, codec: codec as never }],
      })
      const issues = validateDefinitions([definition]).map((issue) => [issue.code, issue.message])
      expect(issues).toEqual(expected ? [[expected[0], `Table app.events column "c" ${expected[1]}`]] : [])
    })
  }
})
